package com.example.budgetapp.processing;
import androidx.room.Room;
import androidx.test.core.app.ApplicationProvider;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import com.example.budgetapp.data.*;
import com.example.budgetapp.data.entity.*;
import com.example.budgetapp.parsing.*;
import com.example.budgetapp.parsing.ParsedTransaction.*;
import com.example.budgetapp.processing.LedgerTypes.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.*;
import org.junit.runner.RunWith;
import static org.junit.Assert.*;
import static com.example.budgetapp.processing.TransactionProcessor.ProcessResult.Status.*;
@RunWith(AndroidJUnit4.class) public class TransactionProcessorTest {
 private LedgerDatabase db;private TransactionProcessor processor;private ManualLedgerRepository manual;private Clock clock=Clock.fixed(Instant.parse("2026-11-11T00:00:00Z"),ZoneOffset.UTC);
 @Before public void setUp(){db=Room.inMemoryDatabaseBuilder(ApplicationProvider.getApplicationContext(),LedgerDatabase.class).addCallback(LedgerDatabase.CALLBACK).allowMainThreadQueries().build();processor=new TransactionProcessor(db,new NotificationParser(TemplateCatalog.fromJson("{\"formatVersion\":1,\"templates\":[]}")),new CategoryMatcher(),clock);manual=new ManualLedgerRepository(db,clock);}
 @After public void close(){db.close();}
 private ParsedTransaction candidate(long amount,String identity){var p=new ParsedTransaction();p.kind=Kind.EXPENSE;p.amountMinor=amount;p.currency="CNY";p.occurredAtMs=1793376000000L;p.timePrecision=TimePrecision.DAY;p.merchant="面馆";p.tradeStatus=TradeStatus.SUCCESS;p.proofs.addAll(EnumSet.allOf(Proof.class));if(identity!=null)p.identities.add(new Identity("PLATFORM_ORDER","wechat",identity));return p;}
 private String event(String key,ParsedTransaction p){SourceEventEntity e=new SourceEventEntity();e.id=UUID.randomUUID().toString();e.sourceType="NOTIFICATION";e.provider="WECHAT";e.accountScopeId="scope";e.eventKey=key;e.capturedAtMs=clock.millis();e.processState="NEW";e.candidateJson=EventCodec.encodeParsed(new ParseResult(ParseResult.Disposition.CANDIDATE,p,"OK","synthetic",1));db.sourceEventDao().insertIgnore(e);return e.id;}
 @Test public void distinctIdsStayDistinctAndManualLateNoticeNeedsReview(){assertEquals(POSTED,processor.process(event("one",candidate(2880,"one"))).status);assertEquals(POSTED,processor.process(event("two",candidate(2880,"two"))).status);assertEquals(2,db.ledgerDao().countPosted());manual.save("manual",new TransactionDraft(Kind.EXPENSE,3000,1793376000000L,TimePrecision.DAY,"面馆","WECHAT","scope",null,""),false);assertEquals(REVIEW,processor.process(event("late",candidate(3000,null))).status);assertEquals(3,db.ledgerDao().countPosted());}
 @Test public void deletedAndEditedFactsSurviveReplayAfterRawPurge(){String first=event("first",candidate(10000,"order"));var posted=processor.process(first);assertEquals(ALREADY_HANDLED,processor.process(first).status);manual.update(posted.transactionId,1,new TransactionDraft(Kind.EXPENSE,8000,1793376000000L,TimePrecision.DAY,"面馆","WECHAT","scope",null,""));db.getOpenHelper().getWritableDatabase().execSQL("UPDATE source_event SET raw_payload=NULL");assertEquals(LINKED,processor.process(event("replay",candidate(10000,"order"))).status);assertEquals(8000,db.ledgerDao().find(posted.transactionId).amountMinor);assertEquals(REVIEW,processor.process(event("weak",candidate(10000,null))).status);manual.delete(posted.transactionId,2);assertEquals(LINKED,processor.process(event("deleted-replay",candidate(10000,"order"))).status);assertEquals("DELETED",db.ledgerDao().find(posted.transactionId).bookingState);assertEquals(0,db.ledgerDao().countPosted());}
 @Test public void exactIdentityConflictNeverOverwrites(){var a=processor.process(event("one",candidate(100,"one")));assertEquals(REVIEW,processor.process(event("conflict",candidate(200,"one"))).status);assertEquals(100,db.ledgerDao().find(a.transactionId).amountMinor);assertEquals(1,db.ledgerDao().countPosted());}
 @Test public void doneFailureRollsBackAndConcurrentReplayIsOnce() throws Exception {String id=event("one",candidate(2880,"one"));db.getOpenHelper().getWritableDatabase().execSQL("CREATE TRIGGER fail_done BEFORE UPDATE ON source_event WHEN NEW.process_state='DONE' BEGIN SELECT RAISE(ABORT,'controlled'); END");assertThrows(RuntimeException.class,()->processor.process(id));assertEquals(0,db.ledgerDao().countPosted());assertEquals("NEW",db.sourceEventDao().find(id).processState);db.getOpenHelper().getWritableDatabase().execSQL("DROP TRIGGER fail_done");ExecutorService pool=Executors.newFixedThreadPool(2);try{var a=pool.submit(()->processor.process(id));var b=pool.submit(()->processor.process(id));Set<TransactionProcessor.ProcessResult.Status> statuses=new HashSet<>(Arrays.asList(a.get().status,b.get().status));assertTrue(statuses.contains(POSTED));assertTrue(statuses.contains(ALREADY_HANDLED));assertEquals(1,db.ledgerDao().countPosted());}finally{pool.shutdownNow();}}
 @Test public void insufficientFactsAndManualPendingNeedReview(){var p=candidate(1,null);p.proofs.remove(Proof.DATE);assertEquals(REVIEW,processor.process(event("bad",p)).status);String id=event("manual",candidate(1,null));var e=db.sourceEventDao().find(id);e.sourceType="MANUAL";db.sourceEventDao().update(e);assertEquals(REVIEW,processor.process(id).status);assertEquals(0,db.ledgerDao().countPosted());}
 @Test public void manualDuplicateWarningUsesOriginalEvidence(){var a=processor.process(event("one",candidate(10000,"one")));manual.update(a.transactionId,1,new TransactionDraft(Kind.EXPENSE,8000,1793376000000L,TimePrecision.DAY,"面馆","WECHAT","scope",null,""));var result=manual.save("manual-old",new TransactionDraft(Kind.EXPENSE,10000,1793376000000L,TimePrecision.DAY,"面馆","WECHAT","scope",null,""),false);assertEquals(ManualLedgerRepository.SaveResult.Status.DUPLICATE_WARNING,result.status);}
 @Test public void weakWindowIs120SecondsAndAccountScopesStaySeparate(){var first=candidate(100,"order");first.timePrecision=TimePrecision.SECOND;processor.process(event("first",first));var near=candidate(100,null);near.timePrecision=TimePrecision.SECOND;near.occurredAtMs+=120000;assertEquals(REVIEW,processor.process(event("near",near)).status);var far=candidate(100,null);far.timePrecision=TimePrecision.SECOND;far.occurredAtMs+=120001;assertEquals(POSTED,processor.process(event("far",far)).status);String scoped=event("scope",candidate(100,"order"));var e=db.sourceEventDao().find(scoped);e.accountScopeId="another";db.sourceEventDao().update(e);assertEquals(POSTED,processor.process(scoped).status);}
 @Test public void refundDoesNotCreateIncomeOrReview(){String id=event("refund",candidate(1,null));var e=db.sourceEventDao().find(id);e.candidateJson=EventCodec.encodeParsed(new ParseResult(ParseResult.Disposition.IGNORED,null,"REFUND_UNSUPPORTED","synthetic",1));db.sourceEventDao().update(e);assertEquals(IGNORED,processor.process(id).status);assertEquals(0,db.ledgerDao().countPosted());assertTrue(db.sourceEventDao().reviews().isEmpty());}
}
